footer_probes.schema:
required group field_id=-1 duckdb_schema {
  optional binary field_id=-1 id (String);
  optional binary field_id=-1 condition_id (String);
  optional binary field_id=-1 oracle (String);
  optional binary field_id=-1 question_id (String);
  optional int64 field_id=-1 outcome_slot_count (Int(bitWidth=64, isSigned=true));
  optional group field_id=-1 payout_numerators (List) {
    repeated group field_id=-1 list {
      optional binary field_id=-1 element (String);
    }
  }
}

required group field_id=-1 root {
  optional binary field_id=-1 asset_id (String);
  optional int64 field_id=-1 block_timestamp;
  optional double field_id=-1 price;
  optional binary field_id=-1 maker (String);
  optional binary field_id=-1 taker (String);
  optional binary field_id=-1 taker_direction (String);
  optional double field_id=-1 usdc_amount;
  optional double field_id=-1 fee_usdc;
  optional binary field_id=-1 condition_id (String);
  optional int64 field_id=-1 outcome_seq;
  optional binary field_id=-1 neg_risk (String);
  optional binary field_id=-1 category (String);
  optional binary field_id=-1 category_refined (String);
  optional binary field_id=-1 outcome_label (String);
  optional binary field_id=-1 winning_outcome_label (String);
  optional binary field_id=-1 resolution_status (String);
  optional double field_id=-1 taker_base_fee;
  optional double field_id=-1 maker_base_fee;
  optional int64 field_id=-1 opens_at (Timestamp(isAdjustedToUTC=true, timeUnit=microseconds, is_from_converted_type=false, force_set_converted_type=false));
  optional int64 field_id=-1 close_at (Timestamp(isAdjustedToUTC=true, timeUnit=microseconds, is_from_converted_type=false, force_set_converted_type=false));
  optional int64 field_id=-1 resolved_at (Timestamp(isAdjustedToUTC=true, timeUnit=microseconds, is_from_converted_type=false, force_set_converted_type=false));
  optional binary field_id=-1 market_slug (String);
  optional double field_id=-1 p_event;
  optional int32 field_id=-1 D (Int(bitWidth=8, isSigned=true));
}
